sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  if (ad.isAdMastered({ onPremisesSyncEnabled: false }) !== false) {
    stepResult.setFailed('a cloud-only object (onPremisesSyncEnabled=false) was wrongly classified as AD-mastered');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
